import{_ as a,C as i,o as s,c as d,j as o,a as n,E as r,a2 as h}from"./chunks/framework.sc8Z_ZE3.js";const x=JSON.parse('{"title":"Commands in a pull request","description":"","frontmatter":{},"headers":[],"relativePath":"review-bot/commands.md","filePath":"review-bot/commands.md"}'),c={name:"review-bot/commands.md"};function l(u,e,m,p,f,g){const t=i("Badge");return s(),d("div",null,[e[0]||(e[0]=o("h1",{id:"commands-in-a-pull-request",tabindex:"-1"},[n("Commands in a pull request "),o("a",{class:"header-anchor",href:"#commands-in-a-pull-request","aria-label":'Permalink to "Commands in a pull request"'},"​")],-1)),r(t,{type:"built",text:"Built"}),e[1]||(e[1]=n(" · ",-1)),r(t,{type:"tried",text:"In real runs"}),e[2]||(e[2]=h(' on a self-hosted GitLab for <code>explain</code>, <code>ignore</code>, <code>pause</code> and <code>resume</code>, over webhook and sync; <code>review full</code>, <code>fix</code> and <code>write tests</code> are built<p>Write a command in a pull request comment, on its own line, starting with <code>@octryx</code>. The bot answers in the same thread.</p><table tabindex="0"><thead><tr><th>Command</th><th>Where</th><th>What it does</th></tr></thead><tbody><tr><td><code>@octryx explain [question]</code></td><td>in a finding&#39;s thread, or anywhere</td><td>Explains that finding, or answers the question about the change, in at most 12 lines. Read-only.</td></tr><tr><td><code>@octryx ignore [reason]</code></td><td>in a finding&#39;s thread</td><td>Removes the finding, replies &quot;🙈 Ignored by …&quot;, resolves the thread and proposes a team rule.</td></tr><tr><td><code>@octryx pause</code></td><td>anywhere</td><td>Stops reviews on this pull request, from webhook and sync.</td></tr><tr><td><code>@octryx resume</code></td><td>anywhere</td><td>Starts them again.</td></tr><tr><td><code>@octryx review full</code></td><td>anywhere</td><td>A full review of the current commit, even if it was reviewed before and even while paused.</td></tr><tr><td><code>@octryx fix [note]</code></td><td>in a finding&#39;s thread, or anywhere</td><td>A fix run: the one finding, or all open blocking findings. Needs fix runs switched on and the <strong>PR fix</strong> workflow on (<a href="#fix">see below</a>).</td></tr><tr><td><code>@octryx write tests [note]</code></td><td>anywhere</td><td>A fix run that may change only test files.</td></tr></tbody></table><p>Anything else after <code>@octryx</code> gets the help text as an answer. Each comment is acted on once, and only on open pull requests.</p><h2 id="who-may-use-them" tabindex="-1">Who may use them <a class="header-anchor" href="#who-may-use-them" aria-label="Permalink to &quot;Who may use them&quot;">​</a></h2><p>The commenter&#39;s host account must be linked to an Octryx AI user (<strong>My settings › Profile</strong>, card <strong>Linked accounts</strong>) who has a role in the Workspace. On top of that:</p><ul><li><strong>GitHub</strong>: write, maintain or admin permission on the repository;</li><li><strong>GitLab</strong>: Developer or higher;</li><li><strong>Bitbucket</strong>: the bot cannot read repository permissions there, so a Workspace admin or owner.</li></ul><p>Anyone else gets one polite refusal.</p><h2 id="ignore" tabindex="-1">ignore <a class="header-anchor" href="#ignore" aria-label="Permalink to &quot;ignore&quot;">​</a></h2><p><code>ignore</code> works only in a finding&#39;s thread. Later passes no longer report a finding in the same file within three lines. A reason is optional but worth giving: the bot turns it into a rule proposal, &quot;Do not report in shop/pricing.py: &lt;finding&gt; (reason: …)&quot;. See <a href="/docs/review-bot/learning">Learning from corrections</a>.</p><h2 id="fix" tabindex="-1">fix <a class="header-anchor" href="#fix" aria-label="Permalink to &quot;fix&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Switch PR fix on first</p><p>A fix run uses the shipped workflow <strong>PR fix</strong>, which is off on a fresh installation. A platform admin switches it on in <strong>Agents › Workflows</strong>, column <strong>On</strong>. While it is off, <code>@octryx fix</code> and <code>@octryx write tests</code> fail, even with <strong>Fix runs</strong> on, and the bot answers in the thread: &quot;Octryx could not start the run: No published workflow &#39;pr-fix&#39;.&quot;</p></div><p>A fix run runs on the commenter&#39;s own machine and subscription, at their cost and with their default coding engine. It needs:</p><ul><li>the workflow <strong>PR fix</strong> switched on (see above);</li><li><strong>Fix runs</strong> switched on for the repository (see <a href="/docs/review-bot/settings#fix-runs">Settings</a>);</li><li>an open pull request that is not from a fork;</li><li>a source branch that is neither the target nor a protected branch.</li></ul><p>Only one fix run per pull request runs at a time. It goes through the same independent review and pushes a new commit; it never force-pushes. Naming an engine in the command (<code>@octryx fix codex</code>) is not supported yet: the bot notes it and uses your default.</p><h2 id="when-commands-arrive" tabindex="-1">When commands arrive <a class="header-anchor" href="#when-commands-arrive" aria-label="Permalink to &quot;When commands arrive&quot;">​</a></h2><p>With a webhook, at once. With <strong>Hourly sync</strong> only, the bot reads new comments every 2 minutes. With <strong>On every push (webhook)</strong> only, commands arrive only through the webhook.</p>',31))])}const y=a(c,[["render",l]]);export{x as __pageData,y as default};
